import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source code (inline extension)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>
#include <cfloat>

__global__ void cross_entropy_kernel(const half* __restrict__ logits,
                                     const int64_t* __restrict__ targets,
                                     float* __restrict__ loss_sum,
                                     int batch,
                                     int classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch) return;

    const half* sample = logits + (size_t)idx * (size_t)classes;

    // 1) max for numeric stability
    float max_val = -FLT_MAX;
    for (int c = 0; c < classes; ++c) {
        float v = __half2float(sample[c]);
        if (v > max_val) max_val = v;
    }

    // 2) sum of exp(logit - max)
    float sum = 0.0f;
    for (int c = 0; c < classes; ++c) {
        float v = __half2float(sample[c]) - max_val;
        sum += expf(v);
    }

    // 3) log-sum-exp
    float log_sum = max_val + logf(sum);

    // 4) target logit
    int64_t t = targets[idx];
    float logit_t = __half2float(sample[t]);

    // 5) loss_i = log_sum - logit_t   ( = -logit_t + log_sum )
    float loss = log_sum - logit_t;

    atomicAdd(loss_sum, loss);
}

torch::Tensor cross_entropy_cuda(torch::Tensor logits,
                                 torch::Tensor targets) {
    // logits: [B, C] half
    // targets: [B] int64
    TORCH_CHECK(logits.is_cuda() && targets.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(logits.dtype() == torch::kHalf, "logits must be fp16");
    TORCH_CHECK(targets.dtype() == torch::kLong, "targets must be int64");
    TORCH_CHECK(logits.dim() == 2, "logits must be 2‑D");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1‑D");
    TORCH_CHECK(logits.size(0) == targets.size(0), "batch size mismatch");

    const int batch = logits.size(0);
    const int classes = logits.size(1);

    // allocate a single‑float accumulator on device and zero it
    auto loss_sum = torch::zeros({1}, torch::device(logits.device()).dtype(torch::kFloat));

    const int threads = 256;
    const int blocks = (batch + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(logits.scalar_type(), "cross_entropy_kernel", ([&] {
        cross_entropy_kernel<<<blocks, threads>>>(
            logits.data_ptr<half>(),
            targets.data_ptr<int64_t>(),
            loss_sum.data_ptr<float>(),
            batch,
            classes);
    }));
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch error: ") + cudaGetErrorString(err));
    }

    // copy back, compute mean, cast to half
    float total = loss_sum.item<float>();
    float mean = total / static_cast<float>(batch);
    auto out = torch::full({1}, static_cast<half>(__float2half(mean)),
                           torch::device(logits.device()).dtype(torch::kHalf));
    return out.squeeze(0);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cross_entropy_cuda", &cross_entropy_cuda, "Cross Entropy (fp16) CUDA");
}
'''

# ----------------------------------------------------------------------
# Build the extension
# ----------------------------------------------------------------------
ext = load_inline(name='cross_entropy_ext',
                  cpp_sources='',
                  cuda_sources=cuda_source,
                  functions=['cross_entropy_cuda'],
                  verbose=False)

# ----------------------------------------------------------------------
# Python wrapper module
# ----------------------------------------------------------------------
def cross_entropy_fp16(logits: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
    """
    Wrapper that forwards to the custom CUDA kernel.
    Returns a scalar tensor (fp16) containing the mean cross‑entropy loss.
    """
    return ext.cross_entropy_cuda(logits, targets)

# ----------------------------------------------------------------------
# Model definition using the custom operator
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for torch.nn.functional.cross_entropy using a custom
    fp16 CUDA kernel.  The interface matches the reference implementation:
        forward(predictions, targets) -> loss (scalar fp16 tensor)
    """
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        return cross_entropy_fp16(predictions, targets)

# ----------------------------------------------------------------------
# Helper functions matching the reference script
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 32768
    num_classes = 4096
    predictions = torch.rand(batch_size, num_classes,
                             dtype=torch.float16,
                             device='cuda')
    targets = torch.randint(0, num_classes,
                            (batch_size,),
                            dtype=torch.long,
                            device='cuda')
    return [predictions, targets]

def get_init_inputs():
    return []

# ----------------------------------------------------------------------
# Simple sanity check (can be removed in production)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    preds, targs = get_inputs()
    model = ModelNew().cuda()
    loss = model(preds, targs)
    print("Loss (fp16 scalar):", loss)
